public final class Money {          // final — no subclassing
    private final String currency;   // immutable fields
    private final double amount;

    public Money(String currency, double amount) {
        if (amount < 0) throw new IllegalArgumentException("Amount cannot be negative");
        this.currency = currency;
        this.amount   = amount;
    }

    // "modification" returns a NEW Money — original unchanged
    public Money add(Money other) {
        if (!currency.equals(other.currency))
            throw new IllegalArgumentException("Currency mismatch");
        return new Money(currency, amount + other.amount);
    }

    // Equality by VALUE — no ID involved
    @Override public boolean equals(Object o) {
        if (!(o instanceof Money m)) return false;
        return currency.equals(m.currency) && amount == m.amount;
    }

    @Override public int hashCode() {
        return Objects.hash(currency, amount);
    }

    // No setters — ever
}


// Usage
Money price    = new Money("USD", 100.0);
Money shipping = new Money("USD", 10.0);
Money total    = price.add(shipping);   // new Money("USD", 110.0)

Money copy = new Money("USD", 100.0);
System.out.println(price.equals(copy)); // true — same value = equal

