#include <iostream>
#include <string>
#include <stdexcept>

class Money {  // no subclassing needed -- value type
public:
    Money(std::string currency, double amount) : currency_(std::move(currency)), amount_(amount) {
        if (amount < 0) throw std::invalid_argument("Amount cannot be negative");
    }

    Money add(const Money& other) const {  // "modification" returns a NEW Money -- original unchanged
        if (currency_ != other.currency_) throw std::invalid_argument("Currency mismatch");
        return Money(currency_, amount_ + other.amount_);
    }

    double getAmount() const { return amount_; }
    const std::string& getCurrency() const { return currency_; }

    bool operator==(const Money& other) const {  // equality by VALUE -- no ID involved
        return currency_ == other.currency_ && amount_ == other.amount_;
    }

    // no setters -- ever

private:
    const std::string currency_;
    const double amount_;
};

int main() {
    Money price("USD", 100.0);
    Money shipping("USD", 10.0);
    Money total = price.add(shipping);   // new Money("USD", 110.0)
    std::cout << total.getAmount() << std::endl;  // 110

    Money copy("USD", 100.0);
    std::cout << (price == copy) << std::endl;  // 1 -- same value = equal
    return 0;
}

