    private final String id;        // set once — never changes
    private       String name;      // can change
    private       String email;     // can change
    private       Address address;  // Value Object — immutable

    public User(String id, String name, String email) {
        this.id    = id;
        this.name  = name;
        this.email = email;
    }

    // Mutation is fine — the ID stays the same
    public void changeName(String newName)      { this.name    = newName; }
    public void changeEmail(String newEmail)    { this.email   = newEmail; }
    public void moveAddress(Address newAddress) { this.address = newAddress; }

    // Equality by ID ONLY — not by name or email
    @Override public boolean equals(Object o) {
        if (!(o instanceof User u)) return false;
        return id.equals(u.id);
    }

    @Override public int hashCode() {
        return Objects.hash(id);
    }
}

